 Mesto (Bratislava III).\n\nSportSync zobrazuje textový prehľad. Registrácia a lístky sú vždy u organizátora (Predpredaj.sk). https://predpredaj.zoznam.sk/sk/listky/domace-zapasy-fc-petrzalka-v-sezone-202627/","cover_url":"https://images.unsplash.com/photo-1574629810360-7efbbe195018?w=800&q=80","city":"Bratislava","starts_at":"2026-08-18T18:00:00.000Z","price_cents":0,"capacity":null,"registered_count":0,"venue_name":"Tehelné pole","latitude":48.1636,"longitude":17.1386,"source_url":"https://predpredaj.zoznam.sk/sk/listky/domace-zapasy-fc-petrzalka-v-sezone-202627/","ticket_url":"https://predpredaj.zoznam.sk/sk/listky/domace-zapasy-fc-petrzalka-v-sezone-202627/","source_name":"Predpredaj.sk","participation_mode":"spectator"}]$json$::jsonb) AS x(
    source text, external_id text, title text, sport text, sport_type text, description text,
    cover_url text, city text, starts_at timestamptz, price_cents int, capacity int,
    registered_count int, venue_name text, latitude float8, longitude float8,
    source_url text, ticket_url text, source_name text, participation_mode text
